import json,re
from pathlib import Path
p=Path('analysis')
final=json.loads((p/'final.json').read_text())['findings']
checks=json.loads((p/'jev-results.json').read_text())['checks']
review=(p/'review.md').read_text()
seen={}
for match in re.finditer(r'^- (F\d+) — ((?:`[A-Za-z0-9_]+`(?:, )?)+)\.$',review,re.M):
 seen[match[1]]=re.findall(r'`([A-Za-z0-9_]+)`',match[2])
assert set(seen)=={f['id'] for f in final}
assert set(x for v in seen.values() for x in v)==set(checks)
for doc in ('review.md','summary.md','open-questions.md'):
 body=(p/doc).read_text()
 for src,line,fragment in re.findall(r'([\w/_.]+\.go):(\d+) \("((?:[^"\n]|"(?!\)))*)"\)',body):
  assert fragment in Path(src).read_text().splitlines()[int(line)-1],(doc,src,line,fragment)
 for link in re.findall(r'\[[^]]+\]\(([^)]+)\)',body):
  assert (p/link).exists(),(doc,link)
print('Final artifacts: all finding-to-batch links, citation fragments, and local Markdown links verified')

